            const inR = right.match(/^(.+?)\s+in\s+(\p{Lu}.*)$/u);
            if (inR && looksLikeName(clean(inR[1])) && (placeIn(verb, inR[2]) || inArea(verb, areaOf(inR[2])))) right = inR[1];
